WITH deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY channel, promo_code ORDER BY starts_on, id) AS rank_in_group FROM promotions QUALIFY rank_in_group = 1) SELECT promo_code, CASE WHEN discount_pct >= 0.32 THEN 'LARGE' ELSE 'SMALL' END AS discount_pct_tier, SUM(discount_pct) FILTER (WHERE promo_code = 'WELCOME5') AS welcome5_total_discount_pct, SIZE(COLLECT_SET(promo_code)) AS num_promo_codes, SUM(CASE WHEN promo_code = 'BUNDLE' THEN discount_pct ELSE 0 END) AS bundle_discount_pct, GROUPING(promo_code) AS grouping_level FROM deduped GROUP BY GROUPING SETS ((promo_code, CASE WHEN discount_pct >= 0.32 THEN 'LARGE' ELSE 'SMALL' END), (promo_code)) HAVING SUM(discount_pct) FILTER (WHERE promo_code = 'WELCOME5') > 0 ORDER BY discount_pct_tier
